const sumLeaveDaysByType = `-- name: SumLeaveDaysByType :many
SELECT
    leave_type,
    COALESCE(SUM(days) FILTER (WHERE status = 'approved'), 0)::float8 AS approved_days,
    COALESCE(SUM(days) FILTER (WHERE status = 'pending'), 0)::float8 AS pending_days,
    COUNT(*) FILTER (WHERE status = 'approved') AS approved_count,
    COUNT(*) FILTER (WHERE status = 'pending') AS pending_count
FROM teacher_leave_requests
WHERE teacher_id = $1
  AND status IN ('pending', 'approved')
  AND EXTRACT(YEAR FROM start_date) = $2::int
GROUP BY leave_type
`

type SumLeaveDaysByTypeParams struct {
	TeacherID uuid.UUID `json:"teacher_id"`
	Year      int32     `json:"year"`
}

type SumLeaveDaysByTypeRow struct {
	LeaveType     string  `json:"leave_type"`
	ApprovedDays  float64 `json:"approved_days"`
	PendingDays   float64 `json:"pending_days"`
	ApprovedCount int64   `json:"approved_count"`
	PendingCount  int64   `json:"pending_count"`
}

// days charged per leave type in a leave (calendar) year, split by whether
// they are approved or still waiting, so a balance check can count both
func (q *Queries) SumLeaveDaysByType(ctx context.Context, arg SumLeaveDaysByTypeParams) ([]SumLeaveDaysByTypeRow, error) {
	rows, err := q.db.Query(ctx, sumLeaveDaysByType, arg.TeacherID, arg.Year)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SumLeaveDaysByTypeRow{}
	for rows.Next() {
		var i SumLeaveDaysByTypeRow
		if err := rows.Scan(
			&i.LeaveType,
			&i.ApprovedDays,
			&i.PendingDays,
			&i.ApprovedCount,
			&i.PendingCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
